CREATE TABLE zones AS SELECT * FROM (VALUES
  (1, 'North', ST_GeomFromText('POLYGON((0 0, 10 0, 10 10, 0 10, 0 0))')),
  (2, 'East',  ST_GeomFromText('POLYGON((10 0, 20 0, 20 10, 10 10, 10 0))')),
  (3, 'South', ST_GeomFromText('POLYGON((0 -10, 10 -10, 10 0, 0 0, 0 -10))'))
) t(zone_id, zone_name, geom);

CREATE TABLE warehouses AS SELECT * FROM (VALUES
  (1, 'Depot Alpha', ST_Point(10, 5)),
  (2, 'Depot Beta',  ST_Point(5, -5)),
  (3, 'Depot Gamma', ST_Point(50, 50))
) t(warehouse_id, warehouse_name, geom);
